actions.script:
def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
def now = ec.user.nowTimestamp
def todayStr = sdf.format(now)
def _cal = java.util.Calendar.getInstance(); _cal.setTime(now)
def _cm0 = java.util.Calendar.getInstance(); _cm0.setTime(now); _cm0.set(java.util.Calendar.DAY_OF_MONTH,1)
def monthStartStr = sdf.format(_cm0.getTime())
// default view = This Month
if (!dashDate) dashDate = monthStartStr
if (!dashDateTo) dashDateTo = todayStr
if (dashDateTo < dashDate) { def _s = dashDate; dashDate = dashDateTo; dashDateTo = _s }
def dayStart = java.sql.Timestamp.valueOf(dashDate + " 00:00:00")
def dayEnd = java.sql.Timestamp.valueOf(dashDateTo + " 23:59:59")

// preset anchors
def _cw = java.util.Calendar.getInstance(); _cw.setTime(now); _cw.set(java.util.Calendar.DAY_OF_WEEK, _cw.getFirstDayOfWeek()); def weekStartStr = sdf.format(_cw.getTime())
def _cy = java.util.Calendar.getInstance(); _cy.setTime(now); _cy.set(java.util.Calendar.DAY_OF_YEAR,1); def yearStartStr = sdf.format(_cy.getTime())
presetActive = 'custom'
if (dashDateTo == todayStr) {
    if (dashDate == todayStr) presetActive='today'
    else if (dashDate == weekStartStr) presetActive='week'
    else if (dashDate == monthStartStr) presetActive='month'
    else if (dashDate == yearStartStr) presetActive='year'
}
urlToday = "?dashDate="+todayStr+"&dashDateTo="+todayStr
urlWeek  = "?dashDate="+weekStartStr+"&dashDateTo="+todayStr
urlMonth = "?dashDate="+monthStartStr+"&dashDateTo="+todayStr
urlYear  = "?dashDate="+yearStartStr+"&dashDateTo="+todayStr
displayDate = dashDate == dashDateTo ? new java.text.SimpleDateFormat("dd MMM yyyy").format(java.sql.Date.valueOf(dashDate)) :
    (new java.text.SimpleDateFormat("dd MMM").format(java.sql.Date.valueOf(dashDate)) + " – " + new java.text.SimpleDateFormat("dd MMM yyyy").format(java.sql.Date.valueOf(dashDateTo)))

// greeting
def _hr = _cal.get(java.util.Calendar.HOUR_OF_DAY)
greeting = _hr < 12 ? 'Good Morning' : (_hr < 17 ? 'Good Afternoon' : 'Good Evening')
_org = ec.user.getPreference("ACTIVE_ORGANIZATION")
orgName = 'there'
try { if (_org && _org != '_NA_') { def _o = ec.entity.find("mantle.party.Organization").condition("partyId", _org).one(); if (_o?.organizationName) orgName = _o.organizationName } } catch (Exception e) {}
if (orgName == 'there') { try { orgName = ec.user.userAccount?.userFullName ?: 'there' } catch (Exception e) {} }

def EC = org.moqui.entity.EntityCondition
def _bd = { v -> (v ?: 0) as BigDecimal }
totalSales = completedTxns.sum { _bd(it.payableAmount) } ?: BigDecimal.ZERO
invoiceCount = completedTxns.size()

// ---- prior equal-length period (WoW / vs-prior) ----
def _pDays = (long)(((dayEnd.getTime() - dayStart.getTime()) / (1000L*60*60*24)) + 1)
def _priorStart = new java.sql.Timestamp(dayStart.getTime() - _pDays*24L*60*60*1000)
def _priorSales = BigDecimal.ZERO
if (_org) { _priorSales = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _org)
    .condition("statusId","PtCompleted").condition("entryDate", EC.GREATER_THAN_EQUAL_TO, _priorStart).condition("entryDate", EC.LESS_THAN, dayStart)
    .list().sum { _bd(it.payableAmount) } ?: BigDecimal.ZERO }
salesWoW = _priorSales > 0 ? Math.round((totalSales.doubleValue() - _priorSales.doubleValue()) * 100.0 / _priorSales.doubleValue()) : (totalSales > 0 ? 100 : 0)

// ---- Total Payables = unpaid purchase invoices (0 for a POS-only tenant) ----
totalPayables = BigDecimal.ZERO
try { if (_org) { ec.entity.find("mantle.account.invoice.Invoice").condition("toPartyId", _org).condition("invoiceTypeEnumId","InvoicePurchase")
    .condition("statusId", EC.NOT_IN, ["InvoicePmtRecvd","InvoiceCancelled","InvoicePaid"]).list().each { totalPayables += (_bd(it.invoiceTotal ?: (_bd(it.totalTaxableAmount)+_bd(it.totalTaxAmount)))) } } } catch (Exception e) {}

// ---- Total Receivable = outstanding on credit bills (payable - paid) ----
totalReceivable = BigDecimal.ZERO; creditBillCount = 0
try { if (_org) { ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _org).condition("isCredit","Y").condition("statusId","PtCompleted").list().each {
    def d = _bd(it.payableAmount) - _bd(it.paidAmount); if (d > 0) { totalReceivable += d; creditBillCount++ } } } } catch (Exception e) {}

// ---- Cash in Hand = cash-method payments in range + (cash-in - cash-out) entries ----
cashInHand = BigDecimal.ZERO
try {
    def _tids = completedTxns.collect { it.transactionId }
    if (_tids) ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId","in",_tids).condition("paymentMethod","Cash").list().each { cashInHand += _bd(it.amount) }
    if (_org) ec.entity.find("zenith.erp.pos.PosCashEntry").condition("organizationPartyId", _org).condition("entryDate", EC.GREATER_THAN_EQUAL_TO, dayStart).condition("entryDate", EC.LESS_THAN_EQUAL_TO, dayEnd).list().each {
        if (it.entryType == 'CashIn') cashInHand += _bd(it.amount); else if (it.entryType == 'CashOut') cashInHand -= _bd(it.amount) }
} catch (Exception e) {}

// ---- Weekly series (last 7 days, oldest->newest) ----
def _wl=[]; def _wd=[]
def _wc = java.util.Calendar.getInstance(); _wc.setTime(dayEnd); _wc.add(java.util.Calendar.DAY_OF_MONTH,-6)  // last 7 days ending at the range end
def _dfmt = new java.text.SimpleDateFormat("EEE")
for (int i=0;i<7;i++) {
    def _ds = new java.sql.Timestamp(_wc.getTimeInMillis()); _wc.set(java.util.Calendar.HOUR_OF_DAY,0); _wc.set(java.util.Calendar.MINUTE,0); _wc.set(java.util.Calendar.SECOND,0)
    def _s0 = new java.sql.Timestamp(_wc.getTimeInMillis()); def _e0c = (java.util.Calendar) _wc.clone(); _e0c.add(java.util.Calendar.DAY_OF_MONTH,1); def _e0 = new java.sql.Timestamp(_e0c.getTimeInMillis())
    def _sum = _org ? (ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _org).condition("statusId","PtCompleted").condition("entryDate", EC.GREATER_THAN_EQUAL_TO, _s0).condition("entryDate", EC.LESS_THAN, _e0).list().sum { _bd(it.payableAmount) } ?: BigDecimal.ZERO) : BigDecimal.ZERO
    _wl.add("'"+_dfmt.format(_wc.getTime())+"'"); _wd.add(_sum.setScale(0, java.math.RoundingMode.HALF_UP).toPlainString())
    _wc.add(java.util.Calendar.DAY_OF_MONTH,1)
}
weeklyLabelsJson = "["+_wl.join(",")+"]"; weeklyDataJson = "["+_wd.join(",")+"]"

// ---- Hourly series for the selected range (aggregate by hour) ----
def _hrs = new BigDecimal[24]; for (int i=0;i<24;i++) _hrs[i]=BigDecimal.ZERO
completedTxns.each { if (it.entryDate) { def c=java.util.Calendar.getInstance(); c.setTime(it.entryDate); _hrs[c.get(java.util.Calendar.HOUR_OF_DAY)] += _bd(it.payableAmount) } }
def _hl=[]; def _hd=[]
for (int h=8; h<=21; h++) { def _lab = (h%12==0?12:h%12) + (h<12?'AM':'PM'); _hl.add("'"+_lab+"'"); _hd.add(_hrs[h].setScale(0, java.math.RoundingMode.HALF_UP).toPlainString()) }
hourlyLabelsJson = "["+_hl.join(",")+"]"; hourlyDataJson = "["+_hd.join(",")+"]"

// ---- Today's hourly (for the "Today" tab) ----
def _tS = java.sql.Timestamp.valueOf(todayStr + " 00:00:00"); def _tE = java.sql.Timestamp.valueOf(todayStr + " 23:59:59")
def _th = new BigDecimal[24]; for (int i=0;i<24;i++) _th[i]=BigDecimal.ZERO
if (_org) ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _org).condition("statusId","PtCompleted").condition("entryDate", EC.GREATER_THAN_EQUAL_TO, _tS).condition("entryDate", EC.LESS_THAN_EQUAL_TO, _tE).list().each { if (it.entryDate) { def c=java.util.Calendar.getInstance(); c.setTime(it.entryDate); _th[c.get(java.util.Calendar.HOUR_OF_DAY)] += _bd(it.payableAmount) } }
def _td=[]; for (int h=8; h<=21; h++) _td.add(_th[h].setScale(0, java.math.RoundingMode.HALF_UP).toPlainString())
todayDataJson = "["+_td.join(",")+"]"

// ---- Top selling products (top 5 for the range) ----
topProducts = []
try {
    def _tids = completedTxns.collect { it.transactionId }
    if (_tids) {
        def _pm = [:]
        ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId","in",_tids).list().each { def k = it.productName ?: it.productId; if (!_pm[k]) _pm[k]=[name:k,qty:BigDecimal.ZERO,total:BigDecimal.ZERO]; _pm[k].qty += _bd(it.quantity); _pm[k].total += _bd(it.lineTotal) }
        _pm.values().sort { -(it.total as BigDecimal) }.take(5).eachWithIndex { p, i -> topProducts.add([rank:(i+1), name:p.name.toString(), qty:ec.l10n.format(p.qty,'#,##0'), total:ec.l10n.format(p.total,'#,##0')]) }
    }
} catch (Exception e) {}

// ---- Recent transactions (last 6) ----
recentTxns = []
completedTxns.take(6).each { recentTxns.add([no:(it.transactionNumber ?: it.transactionId), amt:ec.l10n.format(_bd(it.payableAmount),'#,##0'),
    date: (it.entryDate ? new java.text.SimpleDateFormat("dd MMM").format(it.entryDate) : ''), credit:(it.isCredit == 'Y')]) }

// ---- Pending vendor bills (unpaid purchase invoices — empty for a POS-only tenant) ----
pendingBills = []
try { if (_org) { ec.entity.find("mantle.account.invoice.Invoice").condition("toPartyId", _org).condition("invoiceTypeEnumId","InvoicePurchase")
    .condition("statusId", EC.NOT_IN, ["InvoicePmtRecvd","InvoiceCancelled","InvoicePaid"]).orderBy("dueDate").limit(5).list().each { inv ->
        def _due = inv.dueDate; def _days = _due ? (long)((_due.getTime() - now.getTime())/(1000L*60*60*24)) : 999
        def _pri = _days <= 7 ? 'High' : (_days <= 15 ? 'Medium' : 'Low')
        pendingBills.add([no:inv.invoiceId, amt:ec.l10n.format(_bd(inv.invoiceTotal ?: (_bd(inv.totalTaxableAmount)+_bd(inv.totalTaxAmount))),'#,##0'), due:(_days<0?'Overdue':('Due in '+_days+'d')), pri:_pri]) } } } catch (Exception e) {}

// ================= Business Health (same honest composite as the POS Dashboard) =================
healthMetrics = []; healthScore = 0; healthLabel = '—'; healthHasData = false; healthColor = '#9e9e9e'
try {
    def _pill = [good:['#DCFCE7','#166534'], warn:['#FEF3C7','#92400E'], bad:['#FEE2E2','#991B1B'], na:['#EEF0F5','#64748B']]
    def _colr = { s -> s >= 80 ? 'good' : (s >= 55 ? 'warn' : 'bad') }
    def _addm = { name, avail, score, status, ck -> def p = _pill[ck] ?: _pill.na; healthMetrics.add([name:name, avail:avail, score:score, status:status, pillBg:p[0], pillFg:p[1]]) }
    if (totalSales <= 0 && _priorSales <= 0) { _addm('Sales', false, 0, 'No sales in range', 'na') }
    else { double _g = _priorSales > 0 ? ((totalSales.doubleValue()-_priorSales.doubleValue())*100.0/_priorSales.doubleValue()) : (totalSales>0?100.0:-100.0)
        def _s=_g>=10?95:(_g>=0?80:(_g>=-15?60:35)); def _st=_g>=10?'Strong':(_g>=0?'Good':(_g>=-15?'Fair':'Weak')); def _gp=Math.round(_g)
        _addm('Sales', true, _s, _st+' ('+(_gp>=0?'+':'')+_gp+'% vs prior)', _colr(_s)) }
    if (totalSales <= 0) { _addm('Cash Flow', false, 0, 'No sales in range', 'na') }
    else { def _out=BigDecimal.ZERO; try { ec.entity.find("zenith.erp.pos.PosExpense").condition("expenseDate",EC.GREATER_THAN_EQUAL_TO,dayStart).condition("expenseDate",EC.LESS_THAN_EQUAL_TO,dayEnd).list().each{_out+=_bd(it.amount)} } catch(Exception e){}
        double _r=(_out.doubleValue()*100.0/totalSales.doubleValue()); def _s=_r<5?95:(_r<15?80:(_r<30?60:35)); def _st=_r<5?'Strong':(_r<15?'Healthy':(_r<30?'Watch':'Tight')); _addm('Cash Flow', true, _s, _st, _colr(_s)) }
    def _c90=java.util.Calendar.getInstance(); _c90.setTime(now); _c90.add(java.util.Calendar.DAY_OF_MONTH,-90)
    def _ref90 = _org ? (ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId",_org).condition("statusId","PtCompleted").condition("entryDate",EC.GREATER_THAN_EQUAL_TO,new java.sql.Timestamp(_c90.getTimeInMillis())).list().sum{_bd(it.payableAmount)} ?: BigDecimal.ZERO) : BigDecimal.ZERO
    if (totalReceivable <= 0) { _addm('Receivables', true, 100, 'Nothing outstanding', 'good') }
    else { double _r=_ref90>0?(totalReceivable.doubleValue()/_ref90.doubleValue()):1.0; def _s=_r<0.02?95:(_r<0.10?80:(_r<0.25?55:30)); def _st=_r<0.02?'Healthy':(_r<0.10?'OK':(_r<0.25?'Needs Attention':'High')); _addm('Receivables', true, _s, _st+' ('+ec.l10n.format(totalReceivable,'#,##0')+' owed)', _colr(_s)) }
    def _prodTot = _org ? ec.entity.find("mantle.product.Product").condition("ownerPartyId",_org).count() : 0
    if (_prodTot > 0) {
        def _tracked = ec.entity.find("mantle.product.Product").condition("ownerPartyId",_org).condition("inventoryTracked","Y").count()
        if (_tracked >= 5) { def _low=0; try { ec.entity.find("zenith.erp.inventory.ProductStockView").condition("ownerPartyId",_org).list().each{ def q=_bd(it.totalQoh); def rp=_bd(it.reorderPoint); if (q<=0 || (rp>0&&q<=rp)) _low++ } } catch(Exception e){}
            double _r=(_low*1.0/_tracked); def _s=_r<0.05?95:(_r<0.15?80:(_r<0.30?55:30)); def _st=_r<0.05?'Healthy':(_r<0.15?'Good':(_r<0.30?'Needs Attention':'Low')); _addm('Inventory', true, _s, _st, _colr(_s)) }
        else { def _wp=ec.entity.find("mantle.product.Product").condition("ownerPartyId",_org).condition("mrpAmount",EC.GREATER_THAN,0G).count(); double _r=(_wp*1.0/_prodTot); def _s=_r>=0.95?90:(_r>=0.80?75:(_r>=0.50?55:35)); def _st=_r>=0.80?'Catalog ready':(_r>=0.50?'Some unpriced':'Many unpriced'); _addm('Inventory', true, _s, _st, _colr(_s)) }
        def _cf=ec.entity.conditionFactory
        def _gc=_cf.makeCondition([_cf.makeCondition("gstSlabId",EC.IS_NOT_NULL,null),_cf.makeCondition("isGstExempt",EC.EQUALS,"Y"),_cf.makeCondition("hsnCode",EC.IS_NOT_NULL,null)],EC.OR)
        def _go=ec.entity.find("mantle.product.Product").condition("ownerPartyId",_org).condition(_gc).count(); double _r=(_go*1.0/_prodTot); def _s=_r>=0.95?95:(_r>=0.80?80:(_r>=0.50?55:30)); def _st=_r>=0.95?'Compliant':(_r>=0.80?'Mostly set':(_r>=0.50?'Partial':'Needs setup')); _addm('GST', true, _s, _st, _colr(_s))
    }
    def _av = healthMetrics.findAll { it.avail }; healthHasData = (_av.size() > 0)
    healthScore = healthHasData ? (int) Math.round(_av.sum { it.score } / _av.size()) : 0
    healthLabel = healthScore>=85?'Excellent':(healthScore>=70?'Good':(healthScore>=55?'Fair':'Needs Work'))
    healthColor = healthScore>=85?'#16A34A':(healthScore>=70?'#65A30D':(healthScore>=55?'#D97706':'#DC2626'))
} catch (Exception e) { healthMetrics=[]; healthScore=0; healthLabel='—'; healthHasData=false; healthColor='#9e9e9e' }

fmtSales = ec.l10n.format(totalSales, '#,##,##0')
fmtPayables = ec.l10n.format(totalPayables, '#,##,##0')
fmtReceivable = ec.l10n.format(totalReceivable, '#,##,##0')
fmtCash = ec.l10n.format(cashInHand, '#,##,##0')
